-- Enriquecimento do material UFAC Direito Penal I (aulas 9 a 14).
-- Reexecutável: substitui apenas os arrays de prática do material existente.
-- O conteúdo original em body_md é preservado.
update public.study_materials
set flashcards='[{"b":"Fato típico, ilicitude e culpabilidade. A análise costuma seguir essa ordem.","f":"Aula 9 — Quais são os três substratos do crime na teoria tripartida?"},{"b":"Conduta, resultado, nexo causal e tipicidade.","f":"Aula 9 — Quais são os elementos do fato típico apresentados na apostila?"},{"b":"Formal: adequação da conduta à descrição legal. Material: lesão relevante ao bem jurídico protegido.","f":"Aula 9 — Qual é a diferença entre tipicidade formal e material?"},{"b":"Na conduta, dentro do fato típico, e não na culpabilidade.","f":"Aula 9 — No finalismo, onde ficam dolo e culpa?"},{"b":"Mínima ofensividade; ausência de periculosidade social; reduzidíssimo grau de reprovabilidade; inexpressividade da lesão jurídica.","f":"Aula 9 — Quais são os quatro vetores da insignificância segundo o HC 84.412/SP citado na apostila?"},{"b":"Cogitação, atos preparatórios, execução, consumação e, depois, exaurimento.","f":"Aula 10 — Quais são as fases do iter criminis?"},{"b":"Não. A fase interna da cogitação é impunível.","f":"Aula 10 — A cogitação é punível?"},{"b":"O objetivo-formal: começa a execução quando o agente inicia a prática do verbo do tipo penal.","f":"Aula 10 — Qual critério de início da execução a apostila aponta como tradicionalmente majoritário?"},{"b":"Dolo de consumar; início da execução; não consumação; e interrupção por circunstâncias alheias à vontade do agente.","f":"Aula 10 — Quais são os requisitos da tentativa?"},{"b":"Aplica-se a pena do crime consumado, reduzida de 1/3 a 2/3; quanto mais próximo da consumação, menor tende a ser a redução.","f":"Aula 10 — Como funciona a redução da pena na tentativa?"},{"b":"Na desistência voluntária o agente interrompe a execução podendo continuar. No arrependimento eficaz já esgotou os meios e atua para impedir o resultado, conseguindo evitá-lo.","f":"Aula 10 — Qual é a diferença entre desistência voluntária e arrependimento eficaz?"},{"b":"Depois da consumação, nos crimes sem violência ou grave ameaça, o agente repara o dano ou restitui a coisa voluntariamente, nas condições e prazo legais, com redução da pena.","f":"Aula 10 — O que é arrependimento posterior, conforme o art. 16 do CP?"},{"b":"Quando a consumação é impossível pela ineficácia absoluta do meio ou pela impropriedade absoluta do objeto.","f":"Aula 10 — Quando ocorre crime impossível segundo a ideia central do art. 17 do CP?"},{"b":"É a contrariedade do fato típico ao ordenamento jurídico como um todo; em regra, o fato típico é inicialmente considerado ilícito, salvo causa justificante.","f":"Aula 11 — O que é ilicitude?"},{"b":"Estado de necessidade, legítima defesa, estrito cumprimento do dever legal e exercício regular de direito.","f":"Aula 11 — Quais são as quatro causas de exclusão da ilicitude listadas no art. 23 do CP?"},{"b":"Perigo atual (a apostila também menciona a aceitação doutrinária do iminente), não provocado voluntariamente, inevitabilidade por outro meio, proteção de direito próprio ou alheio e proporcionalidade entre os bens.","f":"Aula 11 — Quais requisitos centrais do estado de necessidade aparecem no art. 24 do CP?"},{"b":"Agressão injusta, atual ou iminente; proteção de direito próprio ou de terceiro; meios necessários usados moderadamente; e conhecimento da situação justificante.","f":"Aula 11 — Quais são os requisitos da legítima defesa?"},{"b":"É ultrapassar os limites necessários ou continuar a reação depois que a agressão cessou.","f":"Aula 11 — O que é excesso na legítima defesa?"},{"b":"Imputabilidade, potencial consciência da ilicitude e exigibilidade de conduta diversa.","f":"Aula 12 — Quais são os três elementos da culpabilidade na teoria normativa pura?"},{"b":"Inimputabilidade: incapacidade inteira de entender a ilicitude ou de se determinar conforme esse entendimento. Semi-imputabilidade: capacidade apenas reduzida, com possibilidade de redução da pena ou substituição por medida de segurança, nos termos legais.","f":"Aula 12 — Qual é a diferença entre inimputabilidade e semi-imputabilidade por doença mental?"},{"b":"Não. Pelo art. 27 do CP, são penalmente inimputáveis e submetidos à legislação especial (ECA).","f":"Aula 12 — Menores de 18 anos são imputáveis penalmente?"},{"b":"Não, ainda que completa, conforme a regra do art. 28 do CP apresentada na apostila.","f":"Aula 12 — A embriaguez voluntária ou culposa exclui a imputabilidade?"},{"b":"Exclui dolo e culpa, tornando o fato atípico, conforme a explicação da apostila.","f":"Aula 13 — Qual é a consequência do erro de tipo essencial inevitável?"},{"b":"Erro de tipo: falsa percepção sobre elemento do tipo, exclui o dolo. Erro de proibição: o agente conhece o que faz, mas acredita que é permitido; afeta a potencial consciência da ilicitude.","f":"Aula 13 — Qual é a diferença entre erro de tipo e erro de proibição?"},{"b":"É o erro que não elimina o dolo nem afasta a responsabilização pelo crime; a apostila exemplifica erro sobre a pessoa, aberratio ictus, aberratio criminis e dolo geral.","f":"Aula 13 — O que é erro de tipo acidental?"},{"b":"O agente imagina uma situação fática que, se existisse, justificaria sua conduta. Pela teoria limitada da culpabilidade descrita na apostila, o erro inevitável isenta; o evitável pode levar à punição por culpa, se prevista.","f":"Aula 13 — O que é descriminante putativa por erro sobre situação de fato?"},{"b":"A teoria monista ou unitária, em forma temperada: todos respondem pelo mesmo crime, com pena individualizada conforme a culpabilidade.","f":"Aula 14 — Qual teoria do concurso de pessoas o Código Penal adota como regra?"},{"b":"Pluralidade de agentes e condutas; relevância causal de cada contribuição; vínculo subjetivo; e unidade de infração.","f":"Aula 14 — Quais são os quatro requisitos do concurso de pessoas apresentados na apostila?"},{"b":"Induzir é fazer nascer a ideia criminosa; instigar é reforçar uma ideia que já existia.","f":"Aula 14 — Qual a diferença entre induzir e instigar?"},{"b":"O coautor divide a execução ou exerce domínio funcional do fato; o partícipe contribui sem executar o núcleo do tipo, por auxílio material ou moral.","f":"Aula 14 — O que distingue coautor de partícipe na explicação da apostila?"},{"b":"Ajuste, determinação, instigação e auxílio não são puníveis se o crime não chega pelo menos a ser tentado.","f":"Aula 14 — O que estabelece o art. 31 do CP, conforme a apostila?"}]'::jsonb,
    quiz='[{"a":true,"q":"Na teoria tripartida apresentada na apostila, crime é composto por fato típico, ilicitude e culpabilidade.","why":"Correto. A apostila usa a concepção tripartida como referência majoritária e organiza a análise nesses três substratos."},{"a":false,"q":"Pelo finalismo descrito na apostila, dolo e culpa são elementos da culpabilidade.","why":"Errado. A apostila explica que dolo e culpa foram deslocados para a conduta, dentro do fato típico."},{"a":false,"q":"A cogitação, por si só, é punível como tentativa quando a intenção criminosa está comprovada.","why":"Errado. A cogitação é fase interna e impunível; a tentativa exige início da execução."},{"a":true,"q":"Há tentativa quando o agente inicia a execução, mas não consuma o crime por circunstâncias alheias à sua vontade.","why":"Correto. É a definição do art. 14, II, do CP reproduzida na apostila."},{"a":true,"q":"Na desistência voluntária, o agente interrompe a execução mesmo podendo prosseguir; no arrependimento eficaz, impede o resultado depois de esgotar os meios executórios.","why":"Correto. Essa é a distinção prática destacada na Aula 10 e associada ao art. 15 do CP."},{"a":false,"q":"O arrependimento posterior ocorre antes da consumação do crime.","why":"Errado. A apostila o situa depois da consumação, nos crimes sem violência ou grave ameaça, observados os requisitos do art. 16."},{"a":true,"q":"O art. 23 do CP lista estado de necessidade, legítima defesa, estrito cumprimento do dever legal e exercício regular de direito.","why":"Correto. São as quatro causas de exclusão da ilicitude enumeradas na Aula 11."},{"a":false,"q":"A legítima defesa autoriza reação contra agressão passada ou contra perigo futuro meramente incerto.","why":"Errado. A apostila exige agressão injusta atual ou iminente; agressão passada caracteriza vingança, e a futura incerta não autoriza reação."},{"a":true,"q":"Na teoria normativa pura, a culpabilidade tem como elementos imputabilidade, potencial consciência da ilicitude e exigibilidade de conduta diversa.","why":"Correto. São os três elementos listados na Aula 12."},{"a":false,"q":"A embriaguez voluntária ou culposa exclui a culpabilidade quando completa.","why":"Errado. A apostila afirma que não exclui a imputabilidade, conforme o art. 28 do CP."},{"a":true,"q":"O erro de tipo essencial sempre exclui o dolo; se inevitável, exclui também a culpa.","why":"Correto. Essa é a distinção da Aula 13: se evitável, pode haver responsabilização culposa quando prevista."},{"a":false,"q":"O Código Penal adota como regra a teoria pluralista no concurso de pessoas.","why":"Errado. A apostila apresenta a teoria monista ou unitária, em forma temperada, como regra do art. 29 do CP."}]'::jsonb,
    updated_at=now()
where slug='ufac-2026-direito-penal-i-aulas-9-14'
  and content_status='under_review';
